css:
.holographic-stack {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 30px;
  perspective: 1000px;
}

.holographic-icon {
  position: relative;
  width: 80px;
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  transform-style: preserve-3d;
}

.holographic-icon svg {
  width: 40px;
  height: 40px;
  position: relative;
  z-index: 3;
  transition: all 0.3s ease;
  filter: drop-shadow(0 0 5px currentColor);
}

.holographic-ring {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 2px solid;
  border-top-color: transparent;
  border-bottom-color: transparent;
  animation: rotate 3s linear infinite;
  opacity: 0.7;
}

.holographic-particles {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    transparent 20%,
    currentColor 20%,
    currentColor 30%,
    transparent 30%,
    transparent 40%,
    currentColor 40%,
    currentColor 50%,
    transparent 50%
  );
  background-size: 15px 15px;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.holographic-pulse {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  box-shadow: 0 0 15px currentColor;
  opacity: 0;
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.holographic-icon.github {
  color: #6e5494;
}

.holographic-icon.github:hover {
  color: #c9510c;
  transform: translateY(-10px) rotateX(20deg);
}

.holographic-icon.github:hover .holographic-ring {
  border-color: #c9510c;
  border-top-color: transparent;
  border-bottom-color: transparent;
}

.holographic-icon.instagram {
  color: #bc2a8d;
}

.holographic-icon.instagram:hover {
  color: linear-gradient(
    90deg,
    rgba(2, 0, 36, 1) 0%,
    rgba(9, 9, 121, 1) 35%,
    rgba(0, 212, 255, 1) 100%
  );
  transform: translateY(-10px) rotateX(20deg);
}

.holographic-icon.instagram:hover .holographic-ring {
  border-color: linear-gradient(
    90deg,
    rgba(2, 0, 36, 1) 0%,
    rgba(9, 9, 121, 1) 35%,
    rgba(0, 212, 255, 1) 100%
  );
  border-top-color: transparent;
  border-bottom-color: transparent;
}

.holographic-icon:hover {
  transform: translateY(-10px) rotateX(20deg);
}

.holographic-icon:hover svg {
  transform: scale(1.2) rotate(10deg);
}

.holographic-icon:hover .holographic-particles {
  opacity: 0.3;
  animation: particles 3s linear infinite;
}

.holographic-icon:hover .holographic-pulse {
  opacity: 0.5;
  animation: pulse 2s ease-out infinite;
}

@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes particles {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 30px 30px;
  }
}

@keyframes pulse {
  0% {
    transform: scale(0.8);
    opacity: 0.5;
  }
  50% {
    transform: scale(1.1);
    opacity: 0.2;
  }
  100% {
    transform: scale(1.3);
    opacity: 0;
  }
}

.holographic-icon::before {
  content: "";
  position: absolute;
  bottom: -10px;
  left: 5%;
  width: 90%;
  height: 20%;
  background: rgba(0, 0, 0, 0.3);
  border-radius: 50%;
  filter: blur(10px);
  transform: rotateX(80deg) translateZ(-20px);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.holographic-icon:hover::before {
  opacity: 0.5;
}
